(function () {
	var data = window.TPT_PREVIEW;
	if (!data) { return; }
	var qtyInput = document.querySelector('[data-preview-qty]');
	var priceEl = document.querySelector('[data-preview-price]');
	var badgeEl = document.querySelector('[data-preview-badge]');
	function esc(t) { return String(t).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[c]; }); }
	function formatNumber(n) {
		var c = data.currency, parts = Number(n).toFixed(c.decimals).split('.');
		parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, c.thousandSeparator);
		return parts.length > 1 ? parts[0] + c.decimalSeparator + parts[1] : parts[0];
	}
	function formatPrice(n) {
		var c = data.currency, v = formatNumber(n);
		switch (c.position) { case 'right': return v + c.symbol; case 'left_space': return c.symbol + ' ' + v; case 'right_space': return v + ' ' + c.symbol; default: return c.symbol + v; }
	}
	function tierFor(q) { var t = data.tiers[0]; for (var i = 0; i < data.tiers.length; i++) { if (q >= data.tiers[i].quantity) { t = data.tiers[i]; } } return t; }
	function each(selector, fn) { Array.prototype.forEach.call(document.querySelectorAll(selector), fn); }
	function highlight(tierQuantity) {
		['tiered-pricing--active', 'tiered-pricing-option-checkbox--active', 'tiered-pricing-dropdown-option--selected'].forEach(function (m) { each('.' + m, function (el) { el.classList.remove(m); }); });
		each('[aria-selected="true"]', function (el) { el.setAttribute('aria-selected', 'false'); });
		var el = document.querySelector('[data-tiered-quantity="' + tierQuantity + '"]');
		if (!el) { return; }
		el.classList.add('tiered-pricing--active');
		if (el.classList.contains('tiered-pricing-dropdown-option')) { el.classList.add('tiered-pricing-dropdown-option--selected'); el.setAttribute('aria-selected', 'true'); }
		var checkbox = el.querySelector('.tiered-pricing-option-checkbox');
		if (checkbox) { checkbox.classList.add('tiered-pricing-option-checkbox--active'); }
	}
	function setText(attr, text) { each('[' + attr + ']', function (el) { el.textContent = text; }); }
	function render() {
		var q = Math.max(1, parseInt(qtyInput ? qtyInput.value : data.quantity, 10) || 1);
		var tier = tierFor(q), unit = tier.price, regular = data.regular, discounted = unit < regular;
		if (priceEl && data.customPrice && data.updatesPrice) {
			var shown = data.total ? unit * q : unit, base = data.total ? regular * q : regular;
			priceEl.innerHTML = data.crossed && discounted ? '<del>' + esc(formatPrice(base)) + '</del> <ins>' + esc(formatPrice(shown)) + '</ins>' : esc(formatPrice(shown));
		}
		// the badge follows the quantity even while the price line itself stays put
		if (badgeEl && data.badge) {
			if (discounted) {
				var saving = regular - unit, discount = Math.floor((saving / regular) * 100 + 1e-9);
				badgeEl.innerHTML = '<br><small class="tiered-pricing-you-save" style="color:' + esc(data.badge.color) + '">' + data.badge.template.replace(/\{tp_ys_price\}/g, esc(formatPrice(saving))).replace(/\{tp_ys_total_price\}/g, esc(formatPrice(saving * q))).replace(/\{tp_ys_percentage_discount\}/g, discount) + '</small>';
			} else {
				badgeEl.innerHTML = '';
			}
		}
		setText('data-tier-pricing-table-summary-product-qty', q);
		setText('data-tier-pricing-table-summary-product-name', data.productName);
		setText('data-tier-pricing-table-summary-product-old-price', discounted ? formatPrice(regular) : '');
		setText('data-tier-pricing-table-summary-product-price', formatPrice(unit));
		setText('data-tier-pricing-table-summary-total', formatPrice(unit * q));
		setText('data-tier-pricing-table-summary-total-with-tax', formatPrice(unit * q));
		highlight(tier.quantity);
	}
	if (qtyInput) { qtyInput.addEventListener('input', render); qtyInput.addEventListener('change', render); }
	if (data.clickable && qtyInput) {
		each('[data-tiered-quantity]', function (el) {
			el.style.cursor = 'pointer';
			el.addEventListener('click', function () { qtyInput.value = el.getAttribute('data-tiered-quantity'); render(); });
		});
	}
	render();
})();
